"""Read-only first real held Hard1F endpoint/DMA attribution; no rerun."""
from pathlib import Path
import argparse,collections,csv,hashlib,json

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--fixtures',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);data={};bindings={}
 for v in['baseline','candidate']:
  q=a.fixtures/v/'pressure-fireball-hard';files={n:q/n for n in['proof.json','deadline-timing.csv','native-cycles.csv','dma-bus.jsonl','cadence.csv','case-end.argb']};bindings.update({str(p):sha(p)for p in files.values()});z=json.loads(files['proof.json'].read_text());t=list(csv.DictReader(files['deadline-timing.csv'].open()));perf=list(csv.DictReader(files['native-cycles.csv'].open()));dma=[json.loads(x)for x in files['dma-bus.jsonl'].read_text().splitlines()];counts=collections.Counter(r['stamp']['frame']for r in dma if r['kind']=='DMA-start');data[v]=dict(game=z,timing=t,perf=perf,DMA=dma,counts=counts)
 b,c=data['baseline'],data['candidate'];differences=[dict(ppuFrame=f,baseline=b['counts'][f],candidate=c['counts'][f])for f in sorted(b['counts']|c['counts'])if b['counts'][f]!=c['counts'][f]];assert differences==[dict(ppuFrame=717,baseline=1,candidate=0)]
 def entry(d):return next(r for r in d['timing']if r['kind']=='NMI-entry'and int(r['ppuFrame'])==717)
 be,ce=entry(b),entry(c);assert int(be['nmiDisable'])==0 and int(ce['nmiDisable'])==255 and int(ce['interruptedPC'])==0x84a8
 bp=next(r for r in b['timing']if r['kind']=='publication-write'and int(r['age'])==239);cp=next(r for r in c['timing']if r['kind']=='publication-write'and int(r['age'])==239);assert int(bp['cpuCycle'])==int(be['cpuCycle'])-7 and int(cp['cpuCycle'])>int(ce['cpuCycle'])
 lost_start=next(r for r in b['DMA']if r['kind']=='DMA-start'and r['stamp']['frame']==717);lost_end=next(r for r in b['DMA']if r['kind']=='DMA-complete'and r['stamp']['frame']==717);assert lost_end['source_exact']and lost_end['data_writes']==256
 costs={}
 for name in['CvAudioPlay','Cv3MusicAndNoiseTick','AudioUpdate']:
  x,y=[next(r for r in d['perf']if int(r['audioEpoch'])==279 and r['name']==name)for d in[b,c]];costs[name]=dict(baseline=int(x['cycles']),candidate=int(y['cycles']),delta=int(y['cycles'])-int(x['cycles']))
 assert costs['CvAudioPlay']['delta']==0 and costs['AudioUpdate']['delta']==costs['Cv3MusicAndNoiseTick']['delta']==26
 no_lag={v:next(r for r in data[v]['timing']if r['kind']=='NoLagSoDraw'and int(r['audioEpoch'])==279)for v in data};assert int(no_lag['candidate']['cpuCycle'])-int(no_lag['baseline']['cpuCycle'])==24
 result=dict(passed=True,accepted=False,status='HELD_ONE_ACTUAL_MISSING_DMA_NOT_MERELY_FINAL_COUNTER',actual_NATIVE_scope='Frozen Hard1F pressure240update pair only',all_actual_DMA_frame_count_differences=differences,baseline_actual_transfer_start=lost_start['stamp'],baseline_actual_transfer_complete=lost_end['stamp'],baseline_complete256bytes=True,baseline_NMI_entry=be,candidate_NMI_entry=ce,baseline_publication=bp,candidate_publication_after_lag_ISR=cp,last_possible_foreground_boundary_cycle=int(ce['cpuCycle'])-7,source_same_audio_epoch279_costs=costs,actual_NoLag_draw_decisions=no_lag,NoLag_entry_delay_cycles=24,uninterrupted_publication_estimate_if_same_main_tail=dict(baseline_plus_delay=int(bp['cpuCycle'])+24,candidate_last_foreground_boundary=int(ce['cpuCycle'])-7,conditional_gap_cycles=int(bp['cpuCycle'])+24-(int(ce['cpuCycle'])-7),qualification='Conditional same-main-tail estimate only; no full interrupted RAM/register snapshot. Actual missed DMA/NmiDisable ownership is directly observed, not inferred from this estimate.'),complete_GAME_counts={v:{k:data[v]['game'][k]for k in['updates','draws','strict_completed_DMA','complete_dma_checks','nmis']}for v in data},CSV_endpoint_omission='Cadence ends at prior endFrame; final two native updates and baseline extra draw are absent from both CSV totals. Full GAME counter and independent actual DMA bus show the one real transfer loss at frame717. No CSV-only pass or masked endpoint.',frozen_inputs=bindings,tool_sha256=sha(__file__),scope='Read-only actual DMA timestamps/hardware complete256-byte proof, NMI stackedPC/disable/publication and exact wrapped audio duration attribution. No new emulator launch, state write, game code optimization, waveform or full-campaign claim.')
 (a.output/'proof.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
